/** Some rules lowercase the label mid-sentence ("Select a valid ${label.toLowerCase()}."). */
function withLowercaseVariants(dict: TranslationDictionary): TranslationDictionary {
  const out: TranslationDictionary = {};
  for (const [en, fil] of Object.entries(dict)) {
    const lowerFil = /^[A-Z]{2}/.test(fil) ? fil : fil.charAt(0).toLowerCase() + fil.slice(1);
    for (const variant of [en.toLowerCase(), en.charAt(0).toLowerCase() + en.slice(1)]) {
      if (variant !== en && !(variant in dict)) out[variant] = lowerFil;
    }
  }
  return out;
}

